// 이메일 클라이언트(특히 Outlook)는 인라인 SVG와 data: URI 이미지를 대부분 차단하므로,
// lucide 아이콘을 미리 PNG로 래스터화해 base64로 박아두고 CID 첨부로 삽입한다.
// (포스터/티켓 배경 이미지와 동일한 CID 첨부 패턴 — lib/ticketMail.ts 참고)
// 생성 스크립트: scratchpad/gen-email-icons.mjs (24x24 lucide path → 64x64 PNG, sharp)

const ICONS_B64: Record<string, string> = {
  popcornGray: "",
  popcornAmber: "",
  triangleAlertAmber: "",
  refreshCwBlue: "",
  circleXRed: "",
  circleCheckGreen: "",
  circleCheckWhite: "",
  clapperboardWhite: "",
  clapperboardRed: "",
  mapPinGray: "",
  hourglassAmber: "",
  hourglassRed: "",
  ticketWhite: "",
  partyPopperWhite: "",
  clipboardListWhite: "",
  sparklesGreen: "",
  // 로고 "영화대교" (Song Myung, 메인 화면 로고와 동일한 글로우). 웹폰트는 메일 앱 대부분이 무시해서 PNG로 굽는다.
  // 150x150 표시 기준 3배(450x450), #0a0a0a 배경 포함. 생성: scratchpad/logo/logo.html → headless Chromium 스크린샷.
  brandLogo: "",
};

export type EmailIconName = keyof typeof ICONS_B64;

export function emailIconBuffer(name: EmailIconName): Buffer {
  return Buffer.from(ICONS_B64[name], 'base64');
}

export function emailIconAttachment(name: EmailIconName, cid: string) {
  return { filename: `${name}.png`, content: emailIconBuffer(name), cid, contentType: 'image/png' };
}

/** 본문에 삽입할 <img> 태그. size는 표시 픽셀 크기(px), 원본은 64x64라 축소만 일어나 선명함. */
export function emailIconImg(cid: string, size: number, extraStyle = ''): string {
  return `<img src="cid:${cid}" width="${size}" height="${size}" alt="" style="display:inline-block; vertical-align:middle;${extraStyle}" />`;
}

/** 메일 상단 "영화대교" 로고 <img>. 첨부는 emailIconAttachment('brandLogo', 'brandLogo')를 함께 넣어야 한다. */
export function brandLogoImg(size = 120): string {
  return `<img src="cid:brandLogo" width="${size}" height="${size}" alt="영화대교" style="display:block; margin:0 auto; width:${size}px; height:${size}px; border:0; color:#f5f5f5; font-size:20px;" />`;
}
